import{_ as i,c as t,o,ag as e,j as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/installation.md","filePath":"zh-CN/guide/installation.md","lastUpdated":1794112334000}'),l={name:"zh-CN/guide/installation.md"};function n(s,a,h,c,d,p){return o(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><h2 id="下载-nicasa" tabindex="-1">下载 Nicasa <a class="header-anchor" href="#下载-nicasa" aria-label="Permalink to &quot;下载 Nicasa&quot;">​</a></h2><p>Nicasa 仅通过 Mac App Store 提供 macOS 版本。应用售价 $4.99，一次性购买即可解锁全部功能。</p><h3 id="下载方式" tabindex="-1">下载方式 <a class="header-anchor" href="#下载方式" aria-label="Permalink to &quot;下载方式&quot;">​</a></h3><ul><li><strong>Mac App Store</strong>：<a href="https://apps.apple.com/us/app/nicasa-image-viewer/id6756032669?mt=12" target="_blank" rel="noreferrer">下载 Nicasa</a> —— $4.99</li><li><strong>Chrome 扩展</strong>：<a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">免费 Chrome 扩展</a> —— 免费</li></ul><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to &quot;安装步骤&quot;">​</a></h2><h3 id="通过-mac-app-store-安装" tabindex="-1">通过 Mac App Store 安装 <a class="header-anchor" href="#通过-mac-app-store-安装" aria-label="Permalink to &quot;通过 Mac App Store 安装&quot;">​</a></h3><ol><li>点击上面的「下载 Nicasa」链接，或在 Mac App Store 中搜索「Nicasa」</li><li>点击「获取」或「购买」完成付费（$4.99）</li><li>应用会自动下载并安装</li><li>从「应用程序」文件夹或启动台启动 Nicasa</li></ol><h3 id="安装-chrome-扩展" tabindex="-1">安装 Chrome 扩展 <a class="header-anchor" href="#安装-chrome-扩展" aria-label="Permalink to &quot;安装 Chrome 扩展&quot;">​</a></h3><ol><li>访问 <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Chrome 应用商店页面</a></li><li>点击「添加至 Chrome」</li><li>在弹窗中确认安装</li><li>扩展即会添加到你的浏览器</li></ol><h4 id="chrome-扩展示范" tabindex="-1">Chrome 扩展示范 <a class="header-anchor" href="#chrome-扩展示范" aria-label="Permalink to &quot;Chrome 扩展示范&quot;">​</a></h4>',11),r("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0"}},[r("iframe",{src:"https://www.youtube.com/embed/NJPweIr1J4s",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:"",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),e('<p><a href="https://www.youtube.com/watch?v=NJPweIr1J4s" target="_blank" rel="noopener">观看：Nicasa Chrome 扩展快速演示</a></p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><p>第一次启动 Nicasa 时：</p><ol><li>系统会提示你授予必要权限（截图功能需要屏幕录制权限）</li><li>应用会扫描「图片」文件夹中的图片</li><li>你可以立即开始浏览图库</li><li>建议安装 Chrome 扩展，以获得更完整的网页看图体验</li></ol><h3 id="finder-同步扩展" tabindex="-1">Finder 同步扩展 <a class="header-anchor" href="#finder-同步扩展" aria-label="Permalink to &quot;Finder 同步扩展&quot;">​</a></h3><p>Nicasa 附带一个 Finder 工具栏扩展，用于快速处理图片：</p><ol><li>启动 Nicasa 后，进入<strong>系统设置</strong> → <strong>扩展</strong> → <strong>访达扩展</strong></li><li>启用 <strong>Nicasa Finder Sync</strong></li><li>在 Finder 工具栏上右键 → <strong>自定义工具栏…</strong></li><li>把 Nicasa 按钮拖到工具栏上</li></ol><p>这样你就能直接在 Finder 里对选中的图片进行优化或编辑。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li><strong>macOS</strong>：10.13 或更高版本</li><li><strong>存储空间</strong>：54.5 MB 可用空间</li><li><strong>内存</strong>：最低 4GB RAM，推荐 8GB</li></ul><h2 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to &quot;权限&quot;">​</a></h2><p>Nicasa 需要以下权限：</p><ul><li><strong>屏幕录制</strong>：用于截图功能（可稍后授予）</li><li><strong>辅助功能</strong>：用于悬浮模式相关功能（可选）</li><li><strong>文件与文件夹</strong>：访问「图片」文件夹及用户选择的目录</li></ul><p>你可以随时在「系统设置 &gt; 隐私与安全性」中修改这些权限。</p><h2 id="安装故障排除" tabindex="-1">安装故障排除 <a class="header-anchor" href="#安装故障排除" aria-label="Permalink to &quot;安装故障排除&quot;">​</a></h2><p>如果安装过程中遇到问题：</p><ul><li>确认你拥有管理员/root 权限</li><li>检查系统是否满足最低要求</li><li>尝试重新下载安装包</li><li>如在 Linux 上安装，请确认已安装所需依赖</li></ul><p>如需更多帮助，请访问我们的<a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">问题反馈页</a>。</p>',18)])])}const g=i(l,[["render",n]]);export{u as __pageData,g as default};
